pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }

    function testFuzz_property(address newLog) public {
        c.Initialized();

        bool ok;
        try c.SetLogFile(newLog) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
